// Where DVM alumni went: every traced alum of the 2017–2023 batches, their latest step (a job, else
// their latest internship) and their history, every company in it, and the tier-1 list the home
// shows (legacy/Legacy.jsx) — plus the two directories of the /legacy page (legacy/page/*).
// research/v8-legacy-tier1.md §2: the exports below and their sort orders are the contract; change
// them only together with the page.
//
// alumni.json is generated by scripts/build-legacy-alumni.mjs from research/v8-alumni-v2.json
// (re-run the script after the research changes). It publishes only confidence-"high" experiences
// and names each person; this module is the only one that knows its shape. People resolve to the
// team records the rest of the site uses (immersive/data team: photo, batch, team, LinkedIn);
// someone those records do not have is skipped (warned once in dev), and a company left with
// nobody is dropped.
import { team, verticals } from "../../../immersive/data";
import { TEAM_ORDER } from "../home/teamStills";
import raw from "./alumni.json";

/**
 * @typedef {{ src: string, kind: "glyph" | "mark" | "tile", color?: string }} Logo
 * @typedef {{ companyId: string, company: Company, kind: "intern" | "full-time", role?: string, year?: number | null }} Experience
 * @typedef {{ slug: string, name: string, photo: string, batch: number, teamId: string, team: string, linkedin?: string,
 *   confidence: "high" | "unconfirmed" | "none", latest: Experience | null, history: Experience[] }} Person
 *   confidence: "high" — published steps; "unconfirmed" — the research found a step but below the
 *   published confidence (so no latest); "none" — nothing found. history: newest first, includes latest.
 * @typedef {{ id: string, name: string, fullName?: string, url?: string, logo?: Logo,
 *   latest: Person[], ever: Person[], fullTime: number, intern: number, tier: 1 | 2, teams: string[], batches: [number, number] }} Company
 *   latest: people whose latest step is here (batch desc, name); ever: anyone with any step here
 *   (batch desc, name); fullTime: of `ever`, people with a full-time step here; intern: the rest
 *   (fullTime + intern === ever.length); tier 1 iff the id is in a TIER1 entry; teams: labels of the
 *   latest people's teams in TEAM_ORDER; batches: [min, max] of the latest people (of `ever` when
 *   nobody is there now).
 * @typedef {{ person: Person, kind: "intern" | "full-time", now: boolean, steps: Experience[], role?: string, year?: number | null, unit?: string }} CompanyPerson
 *   kind: "full-time" if any step at the company is full-time, else "intern"; now: the person's latest
 *   step is at the company; steps: their steps there, newest first; role/year: of the newest step;
 *   unit: the member company's name when the group has several ids and it differs from the display name.
 * @typedef {{ id: string, name: string, fullName?: string, url?: string, logo?: Logo, ids: string[], companies: Company[],
 *   people: CompanyPerson[], count: number, fullTime: number, intern: number, now: number, teams: string[] }} Tier1Company
 *   people sorted: now first, then full-time before intern, then batch desc, then name. count = people.length.
 */

/** The tier-1 list. A string is a company id; an object merges several ids under one name/logo.
 *  Order = prominence (ties in alumni count keep this order). One line to add or remove. */
export const TIER1_IDS = [
  "amazon",
  { id: "samsung", name: "Samsung", ids: ["samsung-r-and-d-institute-india", "samsung-semiconductor"], logoOf: "samsung-r-and-d-institute-india", url: "https://samsung.com" },
  "microsoft", "cisco", "credit-suisse",
  { id: "google", name: "Google", ids: ["google", "google-deepmind"], logoOf: "google", url: "https://google.com" },
  "goldman-sachs", "jpmorgan-chase", "oracle", "stripe", "ubs", "walmart",
  "meta", "uber", "salesforce", "amd", "texas-instruments", "d-e-shaw", "barclays", "american-express",
  // bench: "nielsen", "wells-fargo", "capital-one", "bcg", "pwc", "confluent", "razorpay", "cred", "meesho", "indeed", "media-net", "postman"
];

const MEMBER = new Map(team.map((m) => [m.name.trim(), m]));
const TEAM_LABEL = Object.fromEntries(verticals.map((v) => [v.id, v.label]));
const TEAM_RANK = Object.fromEntries(TEAM_ORDER.map((id, i) => [id, i]));
const rank = (teamId) => TEAM_RANK[teamId] ?? 9;

const byBatchDescName = (a, b) => b.batch - a.batch || a.name.localeCompare(b.name);
const freeze = (a) => Object.freeze(a);

/* ---- companies (filled with people below) */

/** @type {Map<string, Company>} */
const companyMap = new Map(
  raw.companies.map((c) => [
    c.id,
    {
      id: c.id,
      name: c.name,
      fullName: c.fullName,
      url: c.url,
      logo: c.logo ? { src: c.logo.src, kind: c.logo.kind, color: c.logo.color } : undefined,
      latest: [],
      ever: [],
      fullTime: 0,
      intern: 0,
      tier: 2,
      teams: [],
      batches: [0, 0],
    },
  ]),
);

/* ---- people */

const missing = new Set();
/** @type {Person[]} */
const people = [];
for (const p of raw.people) {
  const m = MEMBER.get(p.name.trim());
  if (!m) {
    missing.add(p.name);
    continue;
  }
  /** @type {Experience[]} */
  const history = [];
  for (const h of p.history) {
    const company = companyMap.get(h.companyId);
    if (!company) continue;
    history.push(Object.freeze({ companyId: h.companyId, company, kind: h.kind, role: h.role, year: h.year ?? null }));
  }
  const person = {
    slug: m.slug,
    name: m.name.trim(),
    photo: m.photo,
    batch: m.batch,
    teamId: m.vertical,
    team: TEAM_LABEL[m.vertical] ?? m.vertical,
    linkedin: m.socials?.linkedin,
    confidence: p.confidence,
    latest: history[0] ?? null,
    history: freeze(history),
  };
  people.push(Object.freeze(person));
  if (person.latest) person.latest.company.latest.push(person);
  for (const c of new Set(history.map((h) => h.company))) c.ever.push(person);
}

/** @type {readonly Person[]} batch asc, TEAM_ORDER, name. */
export const PEOPLE = freeze(people.sort((a, b) => a.batch - b.batch || rank(a.teamId) - rank(b.teamId) || a.name.localeCompare(b.name)));

/* ---- who was at a company, and how */

const TEAM_LABELS = (ids) => [...new Set(ids)].sort((a, b) => rank(a) - rank(b)).map((id) => TEAM_LABEL[id] ?? id);

const byCompanyRow = (a, b) =>
  Number(b.now) - Number(a.now) ||
  Number(b.kind === "full-time") - Number(a.kind === "full-time") ||
  b.person.batch - a.person.batch ||
  a.person.name.localeCompare(b.person.name);

/**
 * The CompanyPerson rows for a set of company ids shown under one display name.
 * @param {ReadonlySet<string>} ids
 * @param {string} displayName
 */
function rowsFor(ids, displayName) {
  const multi = ids.size > 1;
  const out = [];
  for (const person of PEOPLE) {
    const steps = person.history.filter((h) => ids.has(h.companyId));
    if (!steps.length) continue;
    const newest = steps[0];
    const unit = multi && newest.company.name !== displayName ? newest.company.name : undefined;
    out.push(
      Object.freeze({
        person,
        kind: steps.some((h) => h.kind === "full-time") ? "full-time" : "intern",
        now: !!person.latest && ids.has(person.latest.companyId),
        steps: freeze(steps),
        role: newest.role,
        year: newest.year ?? null,
        unit,
      }),
    );
  }
  return out.sort(byCompanyRow);
}

for (const c of companyMap.values()) {
  c.latest.sort(byBatchDescName);
  c.ever.sort(byBatchDescName);
  const ft = new Set();
  for (const p of c.ever) if (p.history.some((h) => h.companyId === c.id && h.kind === "full-time")) ft.add(p);
  c.fullTime = ft.size;
  c.intern = c.ever.length - ft.size;
  c.teams = TEAM_LABELS(c.latest.map((p) => p.teamId));
  const years = (c.latest.length ? c.latest : c.ever).map((p) => p.batch);
  c.batches = years.length ? [Math.min(...years), Math.max(...years)] : [0, 0];
}

/* ---- tier 1 */

const tier1 = [];
TIER1_IDS.forEach((entry, order) => {
  const g = typeof entry === "string" ? { id: entry, ids: [entry] } : entry;
  const companies = g.ids.map((id) => companyMap.get(id)).filter((c) => c && c.ever.length > 0);
  if (companies.length !== g.ids.length) {
    if (import.meta.env.DEV) console.warn(`[legacy] TIER1: no company (or nobody) for ${g.ids.filter((id) => !companyMap.get(id)?.ever.length).join(", ")}`);
    if (!companies.length) return;
  }
  const first = companies[0];
  const name = g.name ?? first.name;
  const rows = rowsFor(new Set(companies.map((c) => c.id)), name);
  if (!rows.length) return;
  const logoCo = (g.logoOf && companyMap.get(g.logoOf)) || first;
  tier1.push({
    order,
    t: Object.freeze({
      id: g.id,
      name,
      fullName: g.name ? undefined : first.fullName,
      url: g.url ?? first.url,
      logo: logoCo.logo,
      ids: freeze(companies.map((c) => c.id)),
      companies: freeze(companies),
      people: freeze(rows),
      count: rows.length,
      fullTime: rows.filter((r) => r.kind === "full-time").length,
      intern: rows.filter((r) => r.kind === "intern").length,
      now: rows.filter((r) => r.now).length,
      teams: freeze(TEAM_LABELS(rows.map((r) => r.person.teamId))),
    }),
  });
});

/** @type {readonly Tier1Company[]} count desc, then TIER1_IDS order. Dev-warns and skips an id with no company or no people. */
export const TIER1 = freeze(tier1.sort((a, b) => b.t.count - a.t.count || a.order - b.order).map((x) => x.t));

/** @type {ReadonlySet<string>} every company id in a TIER1 entry. */
export const TIER1_COMPANY_IDS = new Set(TIER1.flatMap((t) => t.ids));

for (const c of companyMap.values()) {
  c.tier = TIER1_COMPANY_IDS.has(c.id) ? 1 : 2;
  freeze(c.latest);
  freeze(c.ever);
  freeze(c.teams);
  freeze(c.batches);
}

/** @type {readonly Company[]} ever.length desc, fullTime desc, name (includes companies nobody is at now). */
export const COMPANIES = freeze(
  [...companyMap.values()]
    .filter((c) => c.ever.length > 0)
    .sort((a, b) => b.ever.length - a.ever.length || b.fullTime - a.fullTime || a.name.localeCompare(b.name))
    .map((c) => Object.freeze(c)),
);

/** @type {ReadonlyMap<string, Person>} */
export const PERSON_BY_SLUG = new Map(PEOPLE.map((p) => [p.slug, p]));
/** @type {ReadonlyMap<string, Company>} */
export const COMPANY_BY_ID = new Map(COMPANIES.map((c) => [c.id, c]));

/** @type {readonly number[]} asc. */
export const BATCHES = freeze([...raw.batches].sort((a, b) => a - b));

/** @type {readonly { id: string, label: string }[]} in TEAM_ORDER. */
export const TEAMS = freeze(TEAM_ORDER.map((id) => Object.freeze({ id, label: TEAM_LABEL[id] ?? id })));

/**
 * Everyone with any published step at one company (or at any of several ids): the CompanyPerson
 * rows, now first, then full-time before intern, then batch desc, then name.
 * @param {Company | string | string[]} companyOrIds
 * @returns {CompanyPerson[]}
 */
export function companyPeople(companyOrIds) {
  const ids = typeof companyOrIds === "string" ? [companyOrIds] : Array.isArray(companyOrIds) ? companyOrIds : [companyOrIds.id];
  const display = typeof companyOrIds === "object" && !Array.isArray(companyOrIds) ? companyOrIds.name : (companyMap.get(ids[0])?.name ?? "");
  return rowsFor(new Set(ids), display);
}

/**
 * Distinct companies in a person's history other than their latest step's, newest first (for a
 * "Previously" line).
 * @param {Person} person
 * @returns {Company[]}
 */
export function previousCompanies(person) {
  const latestId = person.latest?.companyId;
  const seen = new Set();
  const out = [];
  for (const h of person.history) {
    if (h.companyId === latestId || seen.has(h.companyId)) continue;
    seen.add(h.companyId);
    out.push(h.company);
  }
  return out;
}

const withLatest = PEOPLE.filter((p) => p.latest);
/**
 * people: everyone traced · withLatest: with a published latest step · companies: COMPANIES.length ·
 * tier1: TIER1.length · fullTime / intern: kinds of the latest steps (the "now" split).
 */
export const STATS = Object.freeze({
  people: PEOPLE.length,
  withLatest: withLatest.length,
  companies: COMPANIES.length,
  tier1: TIER1.length,
  fullTime: withLatest.filter((p) => p.latest.kind === "full-time").length,
  intern: withLatest.filter((p) => p.latest.kind === "intern").length,
});

/**
 * People whose name, or the name of any company in their history, includes `q` (case-insensitive).
 * An empty query returns everyone.
 * @param {string} q
 * @returns {Person[]}
 */
export function search(q) {
  const s = String(q ?? "").trim().toLowerCase();
  if (!s) return [...PEOPLE];
  return PEOPLE.filter(
    (p) => p.name.toLowerCase().includes(s) || p.history.some((h) => h.company.name.toLowerCase().includes(s) || (h.company.fullName ?? "").toLowerCase().includes(s)),
  );
}

if (import.meta.env.DEV && missing.size) console.warn(`[legacy] no team record for: ${[...missing].join(", ")}`);
